if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require_once dirname(__DIR__).'/app/publishing_desk_policy.php';
require_once dirname(__DIR__).'/app/publishing_desk_billing.php';
$n=0;
function check(bool $condition,string $message): void {global $n;$n++;if(!$condition)throw new RuntimeException($message);}
function rejects(callable $fn,string $message): void {try{$fn();}catch(InvalidArgumentException){check(true,$message);return;}throw new RuntimeException('Expected rejection: '.$message);}
$base=['title'=>'Example fellowship','organisation'=>'Example provider','summary'=>'A verified programme.','description'=>'A detailed opportunity.','eligibility'=>'Registered social enterprises','countries'=>'Kenya','source_url'=>'https://provider.example.org/call','apply_url'=>'https://provider.example.org/apply','verified_on'=>date('Y-m-d'),'timezone'=>'Africa/Nairobi','type'=>'grant'];
$f=desk_fields($base,'opportunity',true);
check($f['amount_min']===null&&$f['amount_max']===null,'Unknown funding remains unknown.');
check($f['deadline']===null&&$f['deadline_mode']==='unknown','No invented deadline.');
check(desk_fields($base+['deadline_mode'=>'rolling'],'opportunity',true)['deadline']===null,'Rolling opportunities need no invented date.');
rejects(fn()=>desk_fields(array_replace($base,['deadline_mode'=>'fixed']),'opportunity',true),'Fixed deadline required.');
rejects(fn()=>desk_fields(array_replace($base,['timezone'=>'Nowhere/Nope']),'opportunity'),'Invalid timezone.');
rejects(fn()=>desk_fields(array_replace($base,['deadline_mode'=>'fixed','deadline'=>'2027-02-30T09:00']),'opportunity'),'Impossible date.');
rejects(fn()=>desk_fields(array_replace($base,['verified_on'=>'2099-01-01']),'opportunity'),'Future verification date.');
rejects(fn()=>desk_fields(array_replace($base,['amount_min'=>'50','amount_max'=>'40']),'opportunity'),'Inverted funding range.');
rejects(fn()=>desk_fields(array_replace($base,['title'=>['bad']]),'opportunity'),'Array input rejected.');
foreach(['http://example.org','https://127.0.0.1/x','https://10.1.2.3/x','https://example.local/x','https://user:pass@example.org','https://example.org:444/x','https://example.org/?access_token=secret','https://example.org/?X-Amz-Signature=secret']as$u)rejects(fn()=>desk_url($u),'Unsafe URL '.$u);
check(desk_url('https://example.org/apply?programme=42')==='https://example.org/apply?programme=42','Public non-secret URL preserved.');
check(desk_money('7500.00')===750000&&desk_decimal(750001)==='7500.01','Integer minor units.');
foreach(['-1','1e3','10.001','1,000','NaN',[],1.2]as$v)rejects(fn()=>desk_money($v),'Invalid monetary input.');
check(desk_provider_minor(42.05)===4205,'JSON provider amount conversion.');
rejects(fn()=>desk_provider_minor(1.001),'Provider cannot silently round fractional minor units.');
$c=[['slug'=>'linkedin','account'=>'https://linkedin.com/in/example','method'=>'manual'],['slug'=>'facebook','account'=>'https://facebook.com/example','method'=>'manual']];
$q=desk_make_quote('weekly',$c);
check($q['minor']===1800000&&$q['rounds']===4&&$q['posts']===8&&$q['articles']===1,'Weekly contract exact deliverables.');
$three=desk_make_quote('three_weekly',$c);check($three['posts']===24,'Three/week means 24 individual posts, not duplicate articles.');
rejects(fn()=>desk_make_quote('weekly',[$c[0],$c[0]]),'Distinct accounts required.');
rejects(fn()=>desk_make_quote('weekly',[$c[0]]),'Two named accounts required.');
rejects(fn()=>desk_make_quote('weekly',[array_replace($c[0],['slug'=>'youtube']),$c[1]]),'Video not sold as a static banner.');
$renewal=desk_make_quote('weekly',$c,['renewal'=>1,'renewal_amount'=>'80.00','currency'=>'USD']);check($renewal['articles']===0&&$renewal['minor']===8000&&$renewal['currency']==='USD','Distribution-only renewal is separately priced.');
$foreign=desk_make_quote('single',$c,['custom_quote'=>1,'renewal_amount'=>'100','currency'=>'USD']);check($foreign['minor']===10000&&$foreign['currency']==='USD','Explicit currency quotation, no invented exchange conversion.');
$t=desk_round_times($q,'2027-01-04T09:00');check(count($t)===4&&$t[3]-$t[0]===21*86400,'Four weekly slots.');
$t3=desk_round_times($three,'2027-01-04T09:00');check(count($t3)===12&&$t3[1]-$t3[0]===2*86400&&$t3[11]-$t3[0]===25*86400,'Three rounds in each of four weeks.');
check(str_contains($q['terms'],'28 days')&&str_contains($q['terms'],'not a calendar month'),'Period wording precise.');
$r=['kind'=>'opportunity','fields'=>$f,'state'=>'draft','creatives'=>[]];$post=['title'=>$f['title'],'standfirst'=>'Summary','content_html'=>'<p>Useful facts.</p>','category_id'=>1];
$r['owner_approval']=desk_digest($r,$post);check(desk_publish_errors($r,$post)===[],'Verified owner-approved organic opportunity can publish.');
$changed=$post;$changed['content_html'].='<p>Changed</p>';check(count(desk_publish_errors($r,$changed))>0,'Changing text invalidates approval.');
$r2=$r;$r2['creatives']['square']=['asset'=>1,'sha256'=>'different'];check(desk_digest($r2,$post)!==$r['owner_approval'],'Changing creative invalidates approval.');
$r2=$r;$r2['fields']['deadline']=time()-1;check(desk_closed($r2),'Expiry enforced.');
$r2=$r;$r2['state']='withdrawn';check(desk_closed($r2),'Withdrawn records closed.');
$r['fields']['source_excerpt']='Public excerpt';$r['fields']['verification_notes']='Private note';$r['fields']['claims_evidence']='Private evidence';$r['fields']['asset_permissions']='Private permissions';$r['client']=['email'=>'private@example.org'];
$ai=desk_ai_material($r);check(!str_contains(json_encode($ai),'private@example.org')&&!isset($ai['facts']['verification_notes'])&&!isset($ai['facts']['claims_evidence']),'Private contact and evidence omitted from AI.');
check($ai['facts']['source_excerpt']==='Public excerpt','Explicit source excerpt available to consented AI.');
check(str_contains(desk_ai_instructions(),'untrusted')&&str_contains(desk_ai_instructions(),'Never ask for contributions'),'AI trust and commercial policy.');
$submission=desk_fields(['title'=>'Public scholarship tip','organisation'=>'Example university','summary'=>'Submitted for review.','description'=>'Submitted for review.','source_url'=>'https://example.edu/scholarship','apply_url'=>'https://apply.example.edu/form','timezone'=>'Africa/Nairobi','type'=>'scholarship','deadline_mode'=>'unknown'],'opportunity');
$flags=desk_submission_flags($submission);
check(isset($flags['official_source_unverified'])&&isset($flags['eligibility_missing'])&&isset($flags['countries_missing'])&&isset($flags['deadline_unknown'])&&isset($flags['application_domain_differs']),'Public intake receives conservative verification flags.');
$submission['eligibility']='Kenyan graduates';$submission['countries']='Kenya';$submission['deadline_mode']='fixed';$submission['deadline']=time()+86400;
$flags=desk_submission_flags($submission);
check(isset($flags['eligibility_unverified'])&&isset($flags['countries_unverified'])&&isset($flags['deadline_unverified']),'Supplied public facts remain unverified until editorial review.');
$frontController=(string)file_get_contents(dirname(__DIR__).'/index.php');
check(str_contains($frontController,"if(str_starts_with(\$path,'/opportunities')||str_starts_with(\$path,'/write/opportunities'))")&&str_contains($frontController,"if(desk_dispatch(\$path))exit;")&&strpos($frontController,"if(desk_dispatch(\$path))exit;")>strpos($frontController,"if(str_starts_with(\$path,'/opportunities')"),'Front controller redirects retired Opportunities before independently dispatching sponsored Publishing Desk routes.');
$routeSource=(string)file_get_contents(dirname(__DIR__).'/app/publishing_desk_routes.php');
check(str_contains($routeSource,"if(\$path==='/write/desk/opportunity/new'){header('Location: '.url('/write/desk'),true,301);return true;}")&&str_contains($routeSource,"array_filter(desk_all(),static fn(\$r)=>(\$r['kind']??'')==='sponsored')"),'Writer Publishing Desk retires direct opportunity creation and hides legacy opportunity records.');
$submitView=(string)file_get_contents(dirname(__DIR__).'/views/desk/submit_opportunity.php');$submitRoutes=(string)file_get_contents(dirname(__DIR__).'/app/publishing_desk_routes.php');$publicIndex=(string)file_get_contents(dirname(__DIR__).'/views/desk/index.php');$writerView=(string)file_get_contents(dirname(__DIR__).'/views/write/desk_edit.php');
check(str_contains($submitView,'public submission → structured verification flags')&&str_contains($submitView,'does not guarantee publication'),'Public form explains the gated catalogue workflow.');
check(str_contains($submitRoutes,"if(\$path==='/opportunities/suggest')")&&str_contains($submitRoutes,"'state']='submitted'")&&str_contains($submitRoutes,"'ai_review'=>'available_after_authorised_editor_consent'"),'Public intake creates a private submitted record and never auto-runs AI.');
check(str_contains($publicIndex,"/opportunities/suggest")&&str_contains($publicIndex,'Submit an employment role'),'Catalogue and employment submission routes remain distinct.');
check(str_contains($writerView,'Public catalogue submission')&&str_contains($writerView,'Verification queue'),'Authorised Writer review exposes submission flags.');

$paid=$r;$paid['kind']='sponsored';$paid['fields']['sponsored']=true;$paid['fields']['sponsor_name']='Example sponsor';$paid['owner_approval']=desk_digest($paid,$post);$paid['client_approval']=$paid['owner_approval'];
check(count(desk_publish_errors($paid,$post))>0,'No paid publication without payment.');
$order=['id'=>str_repeat('a',32),'quote'=>$q,'state'=>'paid','accepted_hash'=>$q['hash'],'merchant'=>'MERCHANT123'];
check(desk_publish_errors($paid,$post,$order)===[],'Exact owner and client approvals plus accepted paid order.');
$order['paused']=true;check(count(desk_publish_errors($paid,$post,$order))>0,'Paused order cannot publish.');unset($order['paused']);
$proof=['status'=>'completed','reference'=>$order['id'],'currency'=>'KES','minor'=>1800000,'transaction'=>'tx1','merchant'=>'MERCHANT123'];
check(desk_payment_matches($order,$proof),'Exact proof accepted.');
foreach(['status'=>'pending','reference'=>'other','currency'=>'USD','minor'=>1799999,'transaction'=>'','merchant'=>'OTHER']as$key=>$v)check(!desk_payment_matches($order,array_replace($proof,[$key=>$v])),'Reject mismatch '.$key);
$order['payment']=['remote'=>'PAYPALORDER1','fingerprint'=>'fp'];$order['quote']['currency']='USD';$order['quote']['minor']=10000;
$d=['id'=>'PAYPALORDER1','status'=>'COMPLETED','purchase_units'=>[['reference_id'=>$order['id'],'custom_id'=>$order['id'],'payee'=>['merchant_id'=>'MERCHANT123'],'amount'=>['currency_code'=>'USD','value'=>'100.00'],'payments'=>['captures'=>[['id'=>'CAPTURE1','status'=>'COMPLETED','amount'=>['currency_code'=>'USD','value'=>'100.00']]]]]]];
check(desk_paypal_proof($order,$d)['status']==='completed','PayPal authoritative complete capture.');
$d['purchase_units'][0]['payments']['captures'][0]['status']='PENDING';check(desk_paypal_proof($order,$d)['status']==='pending','PayPal pending capture not paid.');
$d['purchase_units'][0]['payee']['merchant_id']='OTHER';rejects(fn()=>desk_paypal_proof($order,$d),'PayPal merchant mismatch.');
$p=desk_pesapal_proof($order,['status_code'=>1,'merchant_reference'=>$order['id'],'currency'=>'USD','amount'=>100,'confirmation_code'=>'MPESA1']);check($p['status']==='completed'&&$p['minor']===10000,'Pesapal authoritative proof.');
check(desk_pesapal_proof($order,['status_code'=>3])['status']==='reversed','Pesapal reversals held for review.');
check(count(desk_banner_presets())===4&&desk_banner_presets()['story']===[1080,1920],'Four ready-to-use creative presets.');
echo 'Publishing desk: '.$n." pure assertions passed.\n";
